package com.vaada.models

import androidx.compose.runtime.Composable
import androidx.compose.runtime.staticCompositionLocalOf

/** Language of the UI right now. English until the merchant picks one (fresh install, login and sign-up are English). */
val LocalAppLanguage = staticCompositionLocalOf { AppLanguage.ENGLISH }

/**
 * Every on-screen sentence of the main screens, in the five supported languages (order: en, hi, te, ta, kn).
 * `%s` is filled with String.format. Customer names and money from the ledger are never translated.
 * Telugu / Tamil / Kannada / Hindi wording needs native-speaker review before a public launch.
 */
object UiCatalog {
    private val rows = HashMap<String, List<String>>()
    private fun r(key: String, en: String, hi: String, te: String, ta: String, kn: String) { rows[key] = listOf(en, hi, te, ta, kn) }

    fun get(key: String, lang: AppLanguage, vararg args: Any?): String {
        val row = rows[key] ?: return key           // visible (not silently wrong) if a key is ever missing; a unit test checks all keys
        val text = row[lang.ordinal]
        return if (args.isEmpty()) text else String.format(text, *args)
    }
    val keys: Set<String> get() = rows.keys

